use super::{EffectIntent, EventIdentity, RuleRevisionRef};
use bytes::Bytes;
#[derive(Debug, Clone)] pub enum ExecutionOutcome { Completed, NoMatch, Quarantined { category:String, message:String } }
#[derive(Debug, Clone)] pub struct ExecutionCommit { pub execution_id:String, pub event:EventIdentity, pub rule_revisions:Vec<RuleRevisionRef>, pub outcome:ExecutionOutcome, pub decision_hash:String, pub matched_rule_ids:Vec<String>, pub result_payload:Bytes, pub effects:Vec<EffectIntent>, pub fencing_epoch:u64 }
impl ExecutionCommit { pub fn validate(&self)->Result<(),String>{if self.execution_id.is_empty()||self.decision_hash.is_empty(){return Err("execution_id and decision_hash are required".into())}if self.event.tenant_id.is_empty()||self.event.event_id.is_empty()||self.event.partition_key.is_empty(){return Err("execution event identity is incomplete".into())}if self.fencing_epoch==0{return Err("fencing epoch must be positive".into())}for effect in &self.effects{effect.validate()?;if effect.execution_id!=self.execution_id{return Err("effect execution_id does not match execution commit".into())}if effect.tenant_id!=self.event.tenant_id{return Err("cross-tenant effect is not permitted".into())}}Ok(())} }